import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Historify","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/historify.md","filePath":"new-features/historify.md"}'),i={name:"new-features/historify.md"};function s(d,e,n,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="historify" tabindex="-1">Historify <a class="header-anchor" href="#historify" aria-label="Permalink to &quot;Historify&quot;">​</a></h1><p>Historify downloads normalized broker candles into a local DuckDB database for reuse in charts, research, exports, and backtests. It also manages a symbol watchlist, data catalog, background download jobs, metadata, and recurring schedules.</p><h2 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h2><p>Open <strong>Profile -&gt; Historify</strong>, or navigate to <code>/historify</code> after signing in. The page and its <code>/historify/api</code> administration routes use the Tradeboard browser session.</p><p>Historify administration is not part of the public <code>/api/v1</code> namespace. Public API clients can read stored candles through <code>/api/v1/history</code> with <code>source: &quot;db&quot;</code>.</p><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h2><p>Tradeboard uses six primary configured stores for separate application concerns. Historify owns <code>db/historify.duckdb</code>; it does not replace the main, traffic, latency, health, or sandbox databases.</p><p>The DuckDB schema stores:</p><ul><li>OHLCV and open-interest candles.</li><li>Watchlist entries and symbol metadata.</li><li>Catalog ranges and record counts.</li><li>Download jobs and per-symbol job items.</li><li>Schedules and schedule execution history.</li></ul><p>Candles are upserted by symbol, exchange, interval, and timestamp to avoid duplicate rows. DuckDB connections use the application&#39;s locking and retry behavior.</p><h2 id="watchlist-and-discovery" tabindex="-1">Watchlist And Discovery <a class="header-anchor" href="#watchlist-and-discovery" aria-label="Permalink to &quot;Watchlist And Discovery&quot;">​</a></h2><p>Use the watchlist as the symbol source for bulk downloads and schedules. Symbols are validated against current contract data before persistence. The Historify page also exposes exchange and interval discovery plus futures and options contract selectors.</p><h2 id="download-jobs" tabindex="-1">Download Jobs <a class="header-anchor" href="#download-jobs" aria-label="Permalink to &quot;Download Jobs&quot;">​</a></h2><p>You can download one symbol or create a multi-symbol job from a watchlist, custom selection, option chain, or futures chain. Jobs run in a bounded background pool and report progress to the page through Socket.IO.</p><p>Supported job operations include:</p><ul><li>Pause, resume, cancel, retry, and delete.</li><li>Incremental downloads for missing data before or after the stored range.</li><li>Per-symbol status, downloaded records, timestamps, and broker errors.</li><li>Restart recovery that marks orphaned active jobs failed so they can be retried.</li></ul><p>Historical availability depends on the active broker, requested interval, and requested date range. A completed job can still contain symbol-level no-data or broker errors.</p><h2 id="intervals-and-charts" tabindex="-1">Intervals And Charts <a class="header-anchor" href="#intervals-and-charts" aria-label="Permalink to &quot;Intervals And Charts&quot;">​</a></h2><p><code>1m</code> and <code>D</code> are the primary downloaded and stored intervals. Supported higher and calendar intervals can be derived from stored candles for charts, API queries, and exports. The running application exposes the exact current list through its Historify interval-discovery route.</p><p>Charts display stored historical candles, not a real-time feed. Use them to inspect gaps, range coverage, and unexpected values before relying on a dataset.</p><h2 id="import-and-export" tabindex="-1">Import And Export <a class="header-anchor" href="#import-and-export" aria-label="Permalink to &quot;Import And Export&quot;">​</a></h2><p>Historify accepts validated CSV and Parquet uploads. Sample-file endpoints show the required structure.</p><p>Exports support CSV, TXT, ZIP, and Parquet with symbol, exchange, interval, and date filters. The preview reports matching records and estimated size. Generated temporary files are streamed and removed after download.</p><h2 id="scheduling" tabindex="-1">Scheduling <a class="header-anchor" href="#scheduling" aria-label="Permalink to &quot;Scheduling&quot;">​</a></h2><p>Schedules use the Historify watchlist as their symbol source. Create interval-based or daily schedules, enable or disable them, pause or resume them, trigger them manually, and inspect execution history and the next run time.</p><p>Tradeboard and the broker session must be available when a scheduled download runs. Broker token lifetime and market-data history limits remain broker-specific.</p><h2 id="public-history-api" tabindex="-1">Public History API <a class="header-anchor" href="#public-history-api" aria-label="Permalink to &quot;Public History API&quot;">​</a></h2><p>Choose the history source per request:</p><table tabindex="0"><thead><tr><th>Source</th><th>Behavior</th></tr></thead><tbody><tr><td><code>api</code></td><td>Fetch normalized candles from the active broker</td></tr><tr><td><code>db</code></td><td>Query locally stored Historify candles</td></tr></tbody></table><p>See <a href="./../api-documentation/v1/data-api/history.html">History</a> for the public request and response contract.</p><h2 id="operational-notes" tabindex="-1">Operational Notes <a class="header-anchor" href="#operational-notes" aria-label="Permalink to &quot;Operational Notes&quot;">​</a></h2><ul><li>Stored data is broker-independent after download, but its original quality and availability depend on the broker response.</li><li>Analyzer and live trading databases are separate from Historify.</li><li>Configure the DuckDB file with <code>HISTORIFY_DATABASE_PATH</code>; the default is <code>db/historify.duckdb</code>. Note that <code>.sample.env</code> still ships the obsolete <code>HISTORIFY_DATABASE_URL</code> spelling on line 61, which the code does not read: copying it verbatim leaves the default path in place. Rename the key if you want to relocate the file.</li><li>Back up the DuckDB file before destructive maintenance or host migration.</li></ul>',32)])])}const b=a(i,[["render",s]]);export{u as __pageData,b as default};
